\label{newmain}
Let $a=x_0< x_1< \cdots < x_n=b$ and $a=y_0< y_1< \cdots < y_{n+1}=b$ be two partitions of $[a,b]$ such that $x_{i-1}\leq y_i\leq x_{i}$ ($i=1,2,\ldots, n$). If $f$ is convex on $[a,b]$, then
\begin{eqnarray}\label{new2}
\sum_{i=1}^{n} (x_{i}-x_{i-1}) f(y_i) \leq \sum_{i=0}^{n} (x_{i+1}-x_{i-1}+ y_{i}-y_{i+1}) f(x_i)
\end{eqnarray}
and
\begin{eqnarray}\label{new1}
\sum_{i=0}^{n} (y_{i+1}-y_i) f(x_i) \leq \sum_{i=0}^{n+1} (y_{i+1}-y_{i-1}+ x_{i-1}-x_i) f(y_i),
\end{eqnarray}
where $x_{-1}=y_{-1}=a$ and $x_{n+1}=y_{n+2}=b$.
If $f$ is strictly convex, then inequality (\ref{new2}) (respectively (\ref{new1})) is  strict whenever
$x_{i-1}< y_i< x_{i}$ for some $i\in \{1,2,\ldots, n\}$
(respectively $y_{i}< x_i< y_{i+1}$ for some $i\in \{1,2,\ldots, n-1\}$).

With the assumptions of Theorem \ref{newmain} we may write the inequalities (\ref{new2}) and (\ref{new1}) in following single form
\begin{align}\label{new22}
\nonumber \sum_{i=0}^{n} &(y_{i+1}-y_i) f(x_i) +  \sum_{i=0}^{n-1} (x_{i+1}-x_{i}) f(y_{i+1}) \\
&\leq \min\left\{ \sum_{i=0}^{n} (y_{i+1}-y_i) (f(y_i)+f(y_{i+1})) , \sum_{i=0}^{n-1} (x_{i+1}-x_{i}) (f(x_i)+ f(x_{i+1}))\right\},
\end{align}
which is a monotonicity property between some special Riemann sums.

\label{main}
  With the above assumptions, if $f$ is
convex on $[a,b]$, then we have
\begin{eqnarray}\label{5}
A_{n+1}\leq A_n\hspace{1cm} (n=1,2,\ldots)\hspace{1cm} \mbox{and} \hspace{1cm}
B_n\leq B_{n+1}\hspace{1cm} (n=2,3,\ldots).
\end{eqnarray}
Both inequalities are
strict if $f$ is strictly convex.

If $f>0$ is logarithmically convex on
$[a,b]$, then
\begin{eqnarray}\label{11}
\frac{\sqrt[m-1]{\prod_{i=1}^{m-1}f\left(\frac{(m-i)a+ib}
{m}\right)}}{\sqrt[m]{\prod_{i=1}^mf\left(\frac{(m+1-i)a+ib}
{m+1}\right)}}\leq1\leq
\frac{\sqrt[n+1]{\prod_{i=0}^{n}f\left(\frac{(n-i)a+ib}
{n}\right)}}{\sqrt[n+2]{\prod_{i=0}^{n+1}f\left(\frac{(n+1-i)a+ib}
{n+1}\right)}}
\end{eqnarray}
and
\begin{eqnarray}\label{12}
\nonumber\sqrt[m-1]{\prod_{i=1}^{m-1}f\left(\frac{(m-i)a+ib}
{m}\right)}&\leq& \exp\left(\frac{1}{b-a}\int _a^b \ln f(t)dt\right)\\
&\leq&
\sqrt[n+1]{\prod_{i=0}^{n}f\left(\frac{(n-i)a+ib} {n}\right)},
\end{eqnarray}
where
$m=2,3,\ldots$ and $n=1,2,\ldots$. \\
All inequalities are strict if $f$ is strictly logarithmically convex.

With the above assumptions, if $f$ is
convex on $[a,b]$, then we have
\begin{eqnarray}\label{13'}
 \frac{1}{n(n+2)}\left[S_{n+1}-(b-a)f(a))\right]\le S_n-S_{n+1}\le \frac{1}{n^2}\left[(b-a)f(b)-S_{n+1}\right] \end{eqnarray}
 and
 \begin{eqnarray}\label{14'}
  \frac{1}{n^2}\left[T_{n+1}-(b-a)f(a)\right] \le  T_{n+1}-T_n\le \frac{1}{n(n+2)}\left[(b-a)f(b)-T_{n+1}\right] .
 \end{eqnarray}
                                                                                                                                                                                                                                                                                                                                     
Moreover, except than the case $n=1$ in which equality always
holds in the right of (\ref{13'}) and left hand of (\ref{14'}), all inequalities are
strict if $f$ is strictly convex.\\
If $f$ is concave, all inequalities reverse.

Let $x,y$ be
two vectors in a real normed linear space $X$, not both of them zero, and $p\geq 1$. Then
\begin{eqnarray*}\label{36}
\hspace{-0.5cm}\left(\frac{n\sum_{i=1}^{n-1}\|(n-i)x+iy\|^p}{(n-1)\sum_{i=1}^n\|(n+1-i)x+iy\|^p}\right)^{1/p}
\leq\frac{n}{n+1}\leq\left(\frac{(n+2)\sum_{i=0}^n\|(n-i)x+iy\|^p}{(n+1)\sum_{i=0}^{n+1}\|
(n+1-i)x+iy\|^p}\right)^{1/p}
\end{eqnarray*}
and
\begin{eqnarray}\label{37}
\frac{\sum_{i=1}^{n-1}\|(n-i)x+iy\|^p}{n^p(n-1)} \leq
\int_0^1\|(1-t)x+ty\|^pdt\leq\frac{\sum_{i=0}^n\|(n-i)x+iy\|^p}{n^p(n+1)},
\end{eqnarray}
where in the left hands $n\geq2$ and in the right hands $n\geq1$.\\
Note that (\ref{37}) is a generalization and refinement of the well-known chain inequalities \cite{MPF}
\begin{eqnarray*}\label{38}
\left\|\frac{x+y}{2}\right\|^p\leq
\int_0^1\|(1-t)x+ty\|^pdt\leq\frac{\|x\|^p+\|y\|^p}{2}.
\end{eqnarray*}
If $X$ is strictly convex, then all inequalities are strict if
$x$ and $y$ are linearly independent.

Let $0\leq a<b$. If $r>1$, then
\begin{eqnarray}\label{24}
\hspace{-0.5cm}\left(\frac{n\sum_{i=1}^{n-1}[(n-i)a+ib]^r}{(n-1)\sum_{i=1}^n[(n+1-i)a+ib]^r}\right)^{1/r}
<\frac{n}{n+1}<\left(\frac{(n+2)\sum_{i=0}^n[(n-i)a+ib]^r}{(n+1)\sum_{i=0}^{n+1}[(n+1-i)a+ib]^r}\right)^{1/r}
\end{eqnarray}
and
\begin{eqnarray}\label{25}
\left(\frac{\sum_{i=1}^{n-1}[(n-i)a+ib]^r}{n^r(n-1)}\right)^{1/r}
<L_r(a,b)<\left(\frac{\sum_{i=0}^n[(n-i)a+ib]^r}{n^r(n+1)}\right)^{1/r},
\end{eqnarray}
where in the left hand inequalities, we have $n\geq2$, and in the
right hand ones, $n\geq1$.
\\ If $r<0$ with $a>0$ or $0<r<1$, all
inequalities in (\ref{24}) and (\ref{25}) reverse.\\

If $0<a<b$, then
\begin{eqnarray}\label{26}
\frac{\sqrt[n+1]{\prod_{i=0}^n[(n-i)a+ib]}}
{\sqrt[n+2]{\prod_{i=0}^{n+1}[(n+1-i)a+ib]}}<\frac{n}{n+1}
<\frac{\sqrt[n-1]{\prod_{i=1}^{n-1}[(n-i)a+ib]}}
{\sqrt[n]{\prod_{i=1}^{n}[(n+1-i)a+ib]}}
\end{eqnarray}
and
\begin{eqnarray}\label{27}
\frac{\sqrt[n+1]{\prod_{i=0}^n[(n-i)a+ib]}} {n}<
I(a,b)<\frac{\sqrt[n-1]{\prod_{i=1}^{n-1}[(n-i)a+ib]}}{n},
\end{eqnarray}
where in the left hand inequalities, we have $n\geq1$, and in the
right hand one $n\geq2$.

(i) If we set $a=0$ and $b=1$ in (\ref{23}), we get
for $r>1$,
\begin{eqnarray}\label{28}
\left(\frac{n\sum_{i=1}^{n-1}i^r}{(n-1)\sum_{i=1}^n
i^r}\right)^{1/r}
<\frac{n}{n+1}<\left(\frac{(n+2)\sum_{i=1}^ni^r}{(n+1)\sum_{i=1}^{n+1}i^r}\right)^{1/r},
\end{eqnarray}
where in the left hand inequality, we have $n\geq2$, and in the
right hand one $n\geq1$. It can be seen that (\ref{28}) in turn is
equivalent to
\begin{eqnarray}\label{29}
\hspace{-0.5cm}\frac{n}{n+1}\left(1+\frac{1}{n(n+2)}\right)^{1/r}<
\left((n+1)\sum_{i=1}^ni^r\left/n\sum_{i=1}^{n+1}i^r \right.\right)^{1/r}< \frac{n+1}{n+2} \hspace{1cm}(n\geq 1).
\end{eqnarray}
                                                                
                                        
   
                  
Similarly, if $0<r<1$, all inequalities in (\ref{28}) and so in (\ref{29})
reverse.\\
The inequalities in (\ref{29}) and their reversed forms in the case of
$0<r<1$, give us Bennett inequality (\ref{bennett}) in the case of $r>0$ and a refinement  and converse of the classical
Alzer's inequality (\ref{1}) which are stronger than the result in \cite[Corollary 1]{Ch-Drag}.\\
                                                                                                                                 
(ii) If we take $b=1$ and let $a\to 0+$ in the right hand inequality of (\ref{27}), we get
\begin{eqnarray*}\label{week Sterling}
\sqrt[n]{n!} \geq \frac{n+1}{e}  \hspace{1.5cm}(n=1,2,\ldots).
\end{eqnarray*}
\\
                                                                                                                                 
(iii) If $r<0$, letting $a\rightarrow 0+$ and changing $n$ by $n+1$ in the reversed form of the left hand inequality of (\ref{23}), we obtain
\begin{eqnarray*}\label{30}
\frac{n+1}{n+2}
\leq\left(\frac{(n+1)\sum_{i=1}^{n}i^r}{n\sum_{i=1}^{n+1}
i^r}\right)^{1/r}\hspace{1.5cm}(r<0;~n=1, 2,\ldots),
\end{eqnarray*}
which
                             
is the Bennett inequality (\ref{bennett}) for $r<0$.\\
                                                                                                                                 
(iv) If $r>1$, setting $a=0$ and $b=1$ in (\ref{25}), we get
\begin{eqnarray}\label{0<r<1}
 \frac{(n+1)n^r}{r+1} < \sum_{i=1}^n i^r < \frac{n(n+1)^r}{r+1}  \hspace{1.5cm}( n=1,2,\ldots).
\end{eqnarray}
If $0<r < 1$, then inequalities in (\ref{0<r<1}) reverse.\\
Also, if in the reversed form of the left hand of (\ref{25}), we take $b=1$, let $a\to 0+$ and change $n$ by $n+1$, we obtain
\begin{eqnarray*}\label{serie 1/n}
\sum_{i=1}^n i^r \leq \frac{n(n+1)^r}{r+1}  \hspace{1.5cm}(-1 < r< 0;\ n=1,2,\ldots).
\end{eqnarray*}\\
                                                                                                                                 
                                                                                                                                 
(v) If $0<a<b$, letting $r\rightarrow 0$ in the reversed form of (\ref{24}) and (\ref{25}), we get
a weaker form of (\ref{26}) and (\ref{27}), loosing the strictness of
inequalities.\\
                                                                                                                                 
(vi) If $a\rightarrow 0+$ in (\ref{26}), changing $n$ by $n+1$, we get \cite[Lemma 2.1]{Alzer1994}
\begin{eqnarray*}\label{31}
\frac{n+1}{n+2}
\leq\frac{\sqrt[n]{n!}}{\sqrt[n+1]{(n+1)!}}\hspace{1.5cm}(n=1,2,\ldots),
\end{eqnarray*}
which is a refinement of the inequality of H. Minc and L. Sathre
(\ref{2}).

If $0<a<b\leq \frac{1}{2}$, then
\begin{eqnarray}\label{32}
\frac{\sqrt[m-1]{\prod_{i=1}^{m-1}\frac{m-(m-i)a-i b}
{(m-i)a+ib}}}{\sqrt[m]{\prod_{i=1}^{m}\frac{(m+1)-(m+1-i)a-i b}
{(m+1-i)a+ib}}}<1<\frac{\sqrt[n+1]{\prod_{i=0}^{n}\frac{n-(n-i)a-i b}
{(n-i)a+ib}}}{\sqrt[n+2]{\prod_{i=0}^{n+1}\frac{(n+1)-(n+1-i)a-i b}
{(n+1-i)a+ib}}}
\end{eqnarray}
and
\begin{eqnarray}\label{33}
\sqrt[m-1]{\prod_{i=1}^{m-1}\frac{m-(m-i)a-i b}
{(m-i)a+ib}}<\frac{I(1-a,1-b)}{I(a,b)}<\sqrt[n+1]{\prod_{i=0}^{n}\frac{n-(n-i)a-i
b} {(n-i)a+ib}}
\end{eqnarray}
$$(m=2,3,\ldots;n=1,2,\ldots).$$
In particular,
\begin{eqnarray}\label{34}
{2m-1 \choose m-1}^\frac{1}{m-1}\leq{2m+1 \choose
m}^\frac{1}{m}\hspace{1.5cm}(m=2,3,\ldots),
\end{eqnarray}
and so ${2m+1 \choose m}^\frac{1}{m}$ is an increasing
sequence which tends to $4$. Also, we have \cite[Theorem 3.4]{13RH}
\begin{eqnarray}\label{35}
\frac{2-a-b}
{a+b}<\frac{I(1-a,1-b)}{I(a,b)}<\sqrt{\frac{(1-a)(1-b)} {a
b}}.
\end{eqnarray}

If $0<x\leq\pi/2$, then
\begin{eqnarray}\label{41}
\frac{n-1}{n}\cot\frac{x}{n+1}+\frac{1}{n}\cot x< \cot\frac{x}{n}<
\frac{n+1}{n+2}\cot\frac{x}{n+1}-\frac{1}{n+2}\cot x,
\end{eqnarray}
\begin{eqnarray}\label{42}
               
\frac{1}{n+1}(\sin x\cot\frac{x}{n}+\cos x)<\frac{\sin
x}{x} < \frac{1}{n-1}(\sin x\cot\frac{x}{n}-\cos x),                
\end{eqnarray}
and in particular,
\begin{eqnarray}\label{43}
\frac{n-1}{n}\cot\frac{\pi}{2(n+1)}< \cot\frac{\pi}{2n}<
\frac{n+1}{n+2}\cot\frac{\pi}{2(n+1)}.
\end{eqnarray}\\
where in the left hands of (\ref{41}) and (\ref{43}) and in the right hand of (\ref{42}) we have $n\geq2$ and in the others $n\geq1$.

From (\ref{43}), we have
\begin{eqnarray}\label{44}
\frac{k-1}{k}<\frac{\tan\frac{\pi}{2(k+1)}}{\tan\frac{\pi}{2k}}<\frac{k+1}{k+2}\hspace{1.5cm}(k=2,3,\ldots),
\end{eqnarray}
which by multiplying each side of (\ref{44}) from $k=2$ to $k=n-1$, we
obtain
\begin{eqnarray}\label{45}
\frac{1}{n-1}<\tan\frac{\pi}{2n}<\frac{3}{n+1}\hspace{1.5cm}(n=3,4,\ldots).
\end{eqnarray}
Now using the representations of $\tan2x$, $\cos2x$ and
$\sin2x$ in terms of $\tan x$, and applying (\ref{45}), we get for $n=3,4,\ldots$, the following rational approximations
\begin{eqnarray}\label{46}
\frac{2(n-1)}{n(n-2)}<\tan\frac{\pi}{n}<\frac{6(n+1)}{(n+4)(n-2)},                              
\end{eqnarray}
\begin{eqnarray}\label{47}
\frac{(n-2)(n+4)}{n^2+2n+10}<\cos\frac{\pi}{n}<\frac{n(n-2)}{n^2-2n+2},                              
\end{eqnarray}
and
\begin{eqnarray}\label{48}
\frac{2(n+1)^2}{(n-1)(n^2+2n+10)}<\sin\frac{\pi}{n}<\frac{6(n-1)^2}{(n+1)(n^2-2n+2)}.                              
\end{eqnarray}
                                    
But since
\begin{eqnarray*}
\frac{6(n+1)}{(n+4)(n-2)}-\frac{2(n-1)}{n(n-2)}= \frac{1}{n} \left( \frac{4n^2+8}{n^2+2n-8} \right),
\end{eqnarray*}
\begin{eqnarray*}
\frac{n(n-2)}{n^2-2n+2}-\frac{(n-2)(n+4)}{n^2+2n+10}= \frac{1}{n^2} \left( \frac{16 n^4 -40n^3+16n^2}{n^4+8n^2-16n+20} \right)
\end{eqnarray*}
and
\begin{eqnarray*}
\frac{6(n-1)^2}{(n+1)(n^2-2n+2)}&-&\frac{2(n+1)^2}{(n-1)(n^2+2n+10)}\\
&=& \frac{1}{n} \left( \frac{4n^6-8n^5+44n^4-152n^3+160n^2-64n}{n^6+7n^4-16n^3+12n^2+16n-20} \right),
\end{eqnarray*}
we may write

\begin{eqnarray*}
\tan\frac{\pi}{n}=\frac{2(n-1)}{n(n-2)} +O  \left( \frac{1}{n} \right),
\end{eqnarray*}
\begin{eqnarray*}
\cos\frac{\pi}{n}=\frac{(n-2)(n+4)}{n^2+2n+10} + O \left( \frac{1}{n^2} \right)
\end{eqnarray*}
and
\begin{eqnarray*}
\sin\frac{\pi}{n}=\frac{2(n+1)^2}{(n-1)(n^2+2n+10)} + O  \left( \frac{1}{n} \right).
\end{eqnarray*}
